// DaemonServiceServer is the server API for DaemonService service.
// All implementations must embed UnimplementedDaemonServiceServer
// for forward compatibility.
type DaemonServiceServer interface {
	// 订阅事件流。UI 启动后第一件事，断线需重连。
	Subscribe(*SubscribeRequest, grpc.ServerStreamingServer[Event]) error
	ListHistory(context.Context, *ListHistoryRequest) (*ListHistoryResponse, error)
	DeleteHistory(context.Context, *DeleteHistoryRequest) (*Empty, error)
	// 拉取仅有元数据的大文件记录。立即返回，进度走事件流。
	Fetch(context.Context, *FetchRequest) (*Empty, error)
	// 把某条已就绪的记录重新放进本机剪贴板
	ApplyToClipboard(context.Context, *ApplyToClipboardRequest) (*Empty, error)
	// 只返回已就绪图片（或图片文件）在本机的路径，不改动剪贴板，也不把路径发给对端。
	GetImagePreview(context.Context, *GetImagePreviewRequest) (*GetImagePreviewResponse, error)
	ListDevices(context.Context, *Empty) (*ListDevicesResponse, error)
	CreatePairingCode(context.Context, *Empty) (*CreatePairingCodeResponse, error)
	RedeemPairingCode(context.Context, *RedeemPairingCodeRequest) (*RedeemPairingCodeResponse, error)
	// 配对双方各自确认指纹后才真正互信
	ConfirmPairing(context.Context, *ConfirmPairingRequest) (*Empty, error)
	Unpair(context.Context, *UnpairRequest) (*Empty, error)
	// 重新连接：已是直连时什么也不做；否则马上再试一次直连，打不通照旧走中转。
	// 最多等十几秒，返回那时的连接状态
	Reconnect(context.Context, *ReconnectRequest) (*ReconnectResponse, error)
	// 手动告诉后台服务某台设备的局域网地址：跨网段、或两边都换了地址时用
	SetDeviceAddress(context.Context, *SetDeviceAddressRequest) (*Empty, error)
	// 「搜索附近设备」窗口打开期间保持这个调用，窗口关掉时取消。期间本机在局域网里公开设备名，
	// 并在附近同样打开了这个窗口的设备有变化时推送最新的列表
	WatchNearby(*Empty, grpc.ServerStreamingServer[NearbyDevices]) error
	// 向附近的一台设备发起配对。之后与 RedeemPairingCode 一样，双方核对指纹后各自 ConfirmPairing
	PairNearby(context.Context, *PairNearbyRequest) (*RedeemPairingCodeResponse, error)
	GetConfig(context.Context, *Empty) (*Config, error)
	UpdateConfig(context.Context, *Config) (*Config, error)
	GetStatus(context.Context, *Empty) (*Status, error)
	// 引导用户授予剪贴板权限（打开系统设置面板）
	RequestClipboardPermission(context.Context, *Empty) (*Empty, error)
	// 让系统放行局域网访问：macOS 打开「本地网络」设置面板；
	// Windows 申请管理员权限，在防火墙里放行后台服务。其他平台返回 UNIMPLEMENTED。
	RequestLocalNetworkPermission(context.Context, *Empty) (*Empty, error)
	// These belong to the background service, which also notifies with the UI closed.
	GetNotificationStatus(context.Context, *Empty) (*NotificationStatus, error)
	RequestNotificationPermission(context.Context, *Empty) (*NotificationStatus, error)
	ActivateNotification(context.Context, *NotificationAction) (*Empty, error)
	// 网络出口与打洞诊断：本机有几个出口、各自的公网地址，见 pasteferry-cli nat
	GetNetwork(context.Context, *Empty) (*NetworkInfo, error)
	// 反馈问题用的诊断报告：版本、系统、设置、设备与网络状态、最近的日志。
	// 设备名、服务器地址、公网 IP、用户目录、文件名已换成占位符，用户看过后自己贴进 issue
	ExportDiagnostics(context.Context, *ExportDiagnosticsRequest) (*Diagnostics, error)
	// 临时打开详细日志（调试级别），到时间自动关回去；minutes 为 0 立即关闭
	SetVerboseLog(context.Context, *SetVerboseLogRequest) (*Status, error)
	// 检查更新：从 GitHub 与 Gitee 同时取更新清单，验签后返回比当前新的各版更新日志。见 design/auto-update.md
	CheckForUpdate(context.Context, *CheckForUpdateRequest) (*UpdateInfo, error)
	// 下载并校验最近一次检查到的新版本。取消调用即停止下载
	DownloadUpdate(*DownloadUpdateRequest, grpc.ServerStreamingServer[UpdateProgress]) error
	// 准备好新版本并启动更新助手。返回后界面应当立即退出：助手等它退出后替换文件，再重新打开
	InstallUpdate(context.Context, *InstallUpdateRequest) (*Empty, error)
	// 收藏或取消收藏，见 design/quick-paste-and-favorites.md 第 3 节。
	// 收藏时另存一份，返回新的收藏记录；取消时把收藏放回复制记录的最上面，返回放回去的那一条。
	// 过程中照常推送 clip_added / clip_removed。已过期或已失败的图片、文件返回 FAILED_PRECONDITION
	SetFavorite(context.Context, *SetFavoriteRequest) (*ClipRecord, error)
	// 悬停提示框要显示的完整内容。ClipRecord 的 text_preview 最多 120 个字、换行被压平，不够用
	GetClipDetail(context.Context, *GetClipDetailRequest) (*ClipDetail, error)
	// 给收藏起个别名，列表里显示别名、搜索也认它。alias 为空表示去掉别名
	SetAlias(context.Context, *SetAliasRequest) (*ClipRecord, error)
	// 快捷粘贴窗口进程启动后一直保持这个调用：往上报自己的状态，往下收设置页发来的命令。
	// 调用断开就当作快捷窗口没在运行
	QuickPasteSession(grpc.BidiStreamingServer[QuickPasteStatus, QuickPasteCommand]) error
	// 设置页读快捷窗口的状态；状态变化时另有 quick_paste_changed 事件
	GetQuickPasteStatus(context.Context, *Empty) (*QuickPasteStatus, error)
	// 设置页转给快捷窗口的命令。快捷窗口没在运行时返回 FAILED_PRECONDITION
	SendQuickPasteCommand(context.Context, *QuickPasteCommand) (*Empty, error)
	mustEmbedUnimplementedDaemonServiceServer()
}

